    $read109$SELECT count(*)::text AS actual FROM pg_locks l WHERE l.pid IS DISTINCT FROM pg_backend_pid() AND l.relation IN (SELECT oid FROM pg_class WHERE oid=to_regclass('public.hotel_bookings') UNION SELECT indexrelid FROM pg_index WHERE indrelid=to_regclass('public.hotel_bookings') UNION SELECT reltoastrelid FROM pg_class WHERE oid=to_regclass('public.hotel_bookings') AND reltoastrelid<>0)$read109$),
