    ARRAY['supabase_migrations.schema_migrations']::text[],ARRAY[]::text[],
    $read110$SELECT count(*)::text AS actual FROM supabase_migrations.schema_migrations WHERE version::text='20260811441600'$read110$),
  (111,'reconciliation','reconciliation_anchor_exact','true',
    ARRAY['hotels_lineage_private.reconciliation_receipts']::text[],ARRAY['hotels_lineage_private.current_anchor_is_exact()']::text[],
    $read111$SELECT hotels_lineage_private.current_anchor_is_exact()::text AS actual$read111$),
