),
eligibility AS MATERIALIZED (
  SELECT s.*,
    NOT EXISTS(SELECT 1 FROM unnest(s.required_relations) r(name)
      WHERE to_regclass(r.name) IS NULL)
    AND NOT EXISTS(SELECT 1 FROM unnest(s.required_functions) f(signature)
      LEFT JOIN pg_proc p ON p.oid=to_regprocedure(f.signature)
      WHERE p.oid IS NULL OR p.provolatile NOT IN('s','i')
        OR p.proowner<>'postgres'::regrole)
    AND (cardinality(s.required_functions)=0
      OR NOT EXISTS(SELECT 1 FROM pin_results WHERE exact IS NOT TRUE))
      AS eligible
  FROM specs s
),
measurements AS MATERIALIZED (
  SELECT e.*,
    CASE WHEN eligible THEN
      (xpath('/table/row/actual/text()',
        query_to_xml(e.read_query,true,false,'')))[1]::text
    ELSE NULL END AS actual
  FROM eligibility e
),
leaves AS MATERIALIZED (
  SELECT ordinal,section,leaf_name,expected,actual,
    eligible AND actual IS NOT NULL AND actual=expected AS pass,
    CASE WHEN NOT eligible THEN 'REQUIRED_OBJECT_OR_SOURCE_CONTRACT_UNAVAILABLE'
      WHEN actual IS NULL THEN 'NULL_RESULT_FAIL_CLOSED'
      ELSE 'SAFE_SCALAR_ONLY' END AS safe_context
  FROM measurements
  UNION ALL
  SELECT 112+row_number() OVER(ORDER BY signature)::integer,
    'source_security',signature,'true',exact::text,exact IS TRUE,safe_context
  FROM pin_results
),
totals AS (
  SELECT bool_and(pass IS TRUE) AS ready,
    coalesce(jsonb_agg(leaf_name ORDER BY ordinal)
      FILTER(WHERE pass IS NOT TRUE),'[]'::jsonb) AS blockers,
    count(*) AS required_count,count(*) FILTER(WHERE pass IS TRUE) AS passed_count
  FROM leaves
)
SELECT section,ordinal,leaf_name,expected,actual,pass,safe_context,
  NULL::boolean AS "FINAL_PREACTION_READY",NULL::jsonb AS blocker_codes,
  NULL::bigint AS required_leaf_count,NULL::bigint AS passed_leaf_count
FROM leaves
UNION ALL
SELECT 'final_gate',127,'FINAL_PREACTION_READY','true',
  ready::text,ready,
  'RECOVERY_POINT_EXTERNAL_GATE=HUMAN_CONFIRMED; RECOVERY_POINT=2026-09-08 05:38:06 UTC; SQL_BACKUP_PROOF=NO; NOT_WRITE_AUTHORIZATION',
  ready,blockers,required_count,passed_count
FROM totals
ORDER BY ordinal;
